helpers.cm_abs_i:
func cm_abs_i(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

helpers.cm_floordiv:
func cm_floordiv(a int64, b int64) int64 {
	q := a / b
	if (a%b != 0) && ((a < 0) != (b < 0)) {
		q--
	}
	return q
}

helpers.cm_floormod:
func cm_floormod(a int64, b int64) int64 {
	r := a % b
	if r != 0 && ((r < 0) != (b < 0)) {
		r += b
	}
	return r
}

helpers.cm_gcd:
func cm_gcd(a int64, b int64) int64 {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

helpers.cm_ipow:
func cm_ipow(a int64, b int64) int64 {
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r *= a
		}
		b >>= 1
		if b > 0 {
			a *= a
		}
	}
	return r
}

