helpers.cm_modinv:
func cm_modinv(a int64, m int64) int64 {
	n := m
	if n < 0 {
		n = -n
	}
	r0, r1 := cm_floormod(a, n), n
	s0, s1 := int64(1), int64(0)
	for r1 != 0 {
		q := r0 / r1
		r0, r1 = r1, r0-q*r1
		s0, s1 = s1, s0-q*s1
	}
	if r0 != 1 {
		panic("base is not invertible")
	}
	return cm_floormod(s0, n)
}

helpers.cm_powmod:
func cm_powmod(a int64, b int64, m int64) int64 {
	if b < 0 {
		a = cm_modinv(a, m)
		b = -b
	}
	r := cm_floormod(1, m)
	a = cm_floormod(a, m)
	for b > 0 {
		if b&1 == 1 {
			r = cm_floormod(r*a, m)
		}
		a = cm_floormod(a*a, m)
		b >>= 1
	}
	return r
}

helpers.cm_s_at:
func cm_s_at(s string, i int64) int64 {
	r := []rune(s)
	if i < 0 || i >= int64(len(r)) {
		panic("string index out of range")
	}
	return int64(r[i])
}

helpers.cm_s_chr:
func cm_s_chr(c int64) string {
	if c < 0 || c > 0x10FFFF || (c >= 0xD800 && c <= 0xDFFF) {
		panic("not a Unicode scalar value")
	}
	return string(rune(c))
}

helpers.cm_s_clamp:
func cm_s_clamp(i int64, n int64) int64 {
	if i < 0 {
		i += n
		if i < 0 {
			i = 0
		}
	} else if i > n {
		i = n
	}
	return i
}

helpers.cm_s_cmp:
func cm_s_cmp(a string, b string) int64 {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

helpers.cm_s_codes:
func cm_s_codes(s string) string {
	out := ""
	for i, r := range []rune(s) {
		if i > 0 {
			out += " "
		}
		out += cm_s_from_int(int64(r))
	}
	return out
}

helpers.cm_s_find:
func cm_s_find(s string, sub string, start int64) int64 {
	x, y := []rune(s), []rune(sub)
	n, m := int64(len(x)), int64(len(y))
	i := start
	if i < 0 {
		i += n
		if i < 0 {
			i = 0
		}
	}
	if i > n {
		return -1
	}
	for ; i+m <= n; i++ {
		k := int64(0)
		for k < m && x[i+k] == y[k] {
			k++
		}
		if k == m {
			return i
		}
	}
	return -1
}

helpers.cm_s_from_int:
func cm_s_from_int(v int64) string {
	if v == 0 {
		return "0"
	}
	u := uint64(v)
	if v < 0 {
		u = uint64(-v)
	}
	var b [24]byte
	p := len(b)
	for u > 0 {
		p--
		b[p] = byte('0' + u%10)
		u /= 10
	}
	if v < 0 {
		p--
		b[p] = '-'
	}
	return string(b[p:])
}

helpers.cm_s_ord:
func cm_s_ord(s string) int64 {
	r := []rune(s)
	if len(r) != 1 {
		panic("ord of a string whose length is not 1")
	}
	return int64(r[0])
}

helpers.cm_s_slice:
func cm_s_slice(s string, a int64, b int64) string {
	r := []rune(s)
	n := int64(len(r))
	lo, hi := cm_s_clamp(a, n), cm_s_clamp(b, n)
	if lo >= hi {
		return ""
	}
	return string(r[lo:hi])
}

helpers.cm_s_to_int:
func cm_s_to_int(s string) int64 {
	i, j := 0, len(s)
	for i < j && cm_s_ws(s[i]) {
		i++
	}
	for j > i && cm_s_ws(s[j-1]) {
		j--
	}
	t := s[i:j]
	neg := false
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		neg = t[0] == '-'
		t = t[1:]
	}
	if len(t) == 0 {
		panic("not a decimal integer")
	}
	var v uint64
	for k := 0; k < len(t); k++ {
		if t[k] < '0' || t[k] > '9' {
			panic("not a decimal integer")
		}
		v = v*10 + uint64(t[k]-'0')
	}
	if neg {
		return int64(0 - v)
	}
	return int64(v)
}
